1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  body { font-family: system-ui, sans-serif; max-width: 32rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
9	  h1 { font-size: 1.5rem; }
10	  form { display: flex; gap: .5rem; }
11	  form input { flex: 1; padding: .5rem; font-size: 1rem; }
12	  form input[type="date"] { flex: 0 0 auto; }
13	  button { padding: .5rem .75rem; font-size: 1rem; cursor: pointer; }
14	  ul { list-style: none; padding: 0; margin-top: 1rem; }
15	  li { display: flex; align-items: center; gap: .5rem; padding: .5rem 0; border-bottom: 1px solid #ddd; }
16	  li span { flex: 1; overflow-wrap: anywhere; }
17	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
18	  li time { font-size: .875rem; color: #555; white-space: nowrap; }
19	  li[data-overdue="true"] { background: #fdecea; }
20	  li[data-overdue="true"] time { color: #b00020; font-weight: 600; }
21	  .filters { display: flex; gap: .5rem; margin-top: 1rem; }
22	  .filters button[aria-pressed="true"] { font-weight: 600; }
23	  .search { display: block; width: 100%; box-sizing: border-box; margin-top: 1rem; padding: .5rem; font-size: 1rem; }
24	  li input[data-testid="todo-edit"] { flex: 1; min-width: 0; padding: .25rem; font: inherit; }
25	</style>
26	</head>
27	<body>
28	<h1>Todos</h1>
29	<form id="add-form">
30	  <input data-testid="todo-input" type="text" placeholder="What needs doing?" autocomplete="off">
31	  <input data-testid="todo-due" type="date" aria-label="Due date">
32	  <select data-testid="todo-priority" aria-label="Priority">
33	    <option value="low">Low</option>
34	    <option value="med" selected>Med</option>
35	    <option value="high">High</option>
36	  </select>
37	  <button data-testid="todo-add" type="submit">Add</button>
38	</form>
39	<input class="search" data-testid="search-input" type="search" placeholder="Search" aria-label="Search todos" autocomplete="off">
40	<div class="filters">
41	  <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
42	  <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
43	  <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
44	</div>
45	<div class="filters">
46	  <button data-testid="bulk-mark-all" type="button">Mark all complete</button>
47	  <button data-testid="bulk-clear-completed" type="button">Clear completed</button>
48	</div>
49	<ul data-testid="todo-list"></ul>
50	<script>
51	(function () {
52	  var KEY = 'todos';
53	  var input = document.querySelector('[data-testid="todo-input"]');
54	  var dueInput = document.querySelector('[data-testid="todo-due"]');
55	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
56	  var list = document.querySelector('[data-testid="todo-list"]');
57	  var form = document.getElementById('add-form');
58	  var filterButtons = document.querySelectorAll('[data-filter]');
59	  var searchInput = document.querySelector('[data-testid="search-input"]');
60	  var filter = 'all';
61	  var search = '';
62	  var editing = false;
63	
64	  function load() {
65	    try {
66	      var data = JSON.parse(localStorage.getItem(KEY));
67	      return Array.isArray(data) ? data : [];
68	    } catch (e) {
69	      return [];
70	    }
71	  }
72	
73	  function save() {
74	    try { localStorage.setItem(KEY, JSON.stringify(todos)); } catch (e) {}
75	  }
76	
77	  function newId() {
78	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
79	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
80	  }
81	
82	  // Project rule: due dates are plain YYYY-MM-DD strings, read as LOCAL calendar dates.
83	  // Never parse them through Date/UTC. Overdue = due date strictly before today's local date.
84	  function validDue(value) {
85	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
86	  }
87	
88	  function pad(n) { return (n < 10 ? '0' : '') + n; }
89	
90	  function localToday(now) {
91	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
92	  }
93	
94	  // Zero-padded YYYY-MM-DD strings sort lexicographically in date order.
95	  function isOverdue(due, today) {
96	    return !!validDue(due) && due < today;
97	  }
98	
99	  // Project rule: priority is low|med|high; anything else (including missing) is med.
100	  function validPriority(value) {
101	    return value === 'low' || value === 'high' ? value : 'med';
102	  }
103	
104	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
105	
106	  // Project rule: priority order high, med, low; insertion order within the same priority.
107	  // Stable sort keeps insertion order for ties.
108	  function byPriority(list) {
109	    return list
110	      .map(function (t, i) { return { t: t, i: i }; })
111	      .sort(function (a, b) {
112	        return (PRIORITY_RANK[validPriority(a.t.priority)] - PRIORITY_RANK[validPriority(b.t.priority)]) || (a.i - b.i);
113	      })
114	      .map(function (x) { return x.t; });
115	  }
116	
117	  // Search: case-insensitive substring on text; applied on top of the status filter.
118	  function matchesSearch(todo, term) {
119	    return !term || String(todo.text).toLowerCase().indexOf(term.toLowerCase()) !== -1;
120	  }
121	
122	  // Project rule: active todos first, completed below; within each group, sorted by priority.
123	  function visibleTodos(all, f, term) {
124	    all = all.filter(function (t) { return matchesSearch(t, term); });
125	    var active = byPriority(all.filter(function (t) { return !t.completed; }));
126	    var done = byPriority(all.filter(function (t) { return !!t.completed; }));
127	    if (f === 'active') return active;
128	    if (f === 'completed') return done;
129	    return active.concat(done);
130	  }
131	
132	  function render() {
133	    list.textContent = '';
134	    renderedDay = localToday(new Date());
135	    filterButtons.forEach(function (b) {
136	      b.setAttribute('aria-pressed', String(b.dataset.filter === filter));
137	    });
138	    visibleTodos(todos, filter, search).forEach(function (todo) {
139	      var li = document.createElement('li');
140	      li.setAttribute('data-testid', 'todo-item');
141	      li.setAttribute('data-completed', String(!!todo.completed));
142	      li.setAttribute('data-overdue', String(isOverdue(todo.due, renderedDay)));
143	      li.setAttribute('data-priority', validPriority(todo.priority));
144	      li.dataset.id = todo.id;
145	
146	      var toggle = document.createElement('input');
147	      toggle.setAttribute('data-testid', 'todo-toggle');
148	      toggle.type = 'checkbox';
149	      toggle.checked = !!todo.completed;
150	      toggle.setAttribute('aria-label', 'Mark complete');
151	      toggle.addEventListener('change', function () {
152	        todo.completed = toggle.checked;
153	        save();
154	        render();
155	      });
156	
157	      var text = document.createElement('span');
158	      text.setAttribute('data-testid', 'todo-text');
159	      text.textContent = todo.text;
160	      text.addEventListener('dblclick', function () { startEdit(todo, text); });
161	
162	      var del = document.createElement('button');
163	      del.setAttribute('data-testid', 'todo-delete');
164	      del.type = 'button';
165	      del.textContent = 'Delete';
166	      del.addEventListener('click', function () {
167	        todos = todos.filter(function (t) { return t.id !== todo.id; });
168	        save();
169	        render();
170	      });
171	
172	      li.appendChild(toggle);
173	      li.appendChild(text);
174	      if (validDue(todo.due)) {
175	        var due = document.createElement('time');
176	        due.setAttribute('data-testid', 'todo-due-date');
177	        due.dateTime = todo.due;
178	        due.textContent = 'Due ' + todo.due;
179	        li.appendChild(due);
180	      }
181	      li.appendChild(del);
182	      list.appendChild(li);
183	    });
184	  }
185	
186	  // Enter and blur commit, Escape cancels. Empty text keeps the original.
187	  function startEdit(todo, span) {
188	    var field = document.createElement('input');
189	    field.type = 'text';
190	    field.setAttribute('data-testid', 'todo-edit');
191	    field.setAttribute('aria-label', 'Edit todo');
192	    field.value = todo.text;
193	    var finished = false;
194	    editing = true;
195	
196	    function finish(commit) {
197	      if (finished) return;
198	      finished = true;
199	      editing = false;
200	      var value = field.value.trim();
201	      if (commit && value) {
202	        todo.text = value;
203	        save();
204	      }
205	      render();
206	    }
207	
208	    field.addEventListener('keydown', function (e) {
209	      if (e.key === 'Enter') { e.preventDefault(); finish(true); }
210	      else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
211	    });
212	    field.addEventListener('blur', function () { finish(true); });
213	
214	    span.replaceWith(field);
215	    field.focus();
216	    field.select();
217	  }
218	
219	  var todos = load();
220	  var renderedDay = '';
221	
222	  form.addEventListener('submit', function (e) {
223	    e.preventDefault();
224	    var text = input.value.trim();
225	    if (!text) return;
226	    todos.push({ id: newId(), text: text, completed: false, createdAt: Date.now(), due: validDue(dueInput.value), priority: validPriority(priorityInput.value) });
227	    save();
228	    render();
229	    input.value = '';
230	    dueInput.value = '';
231	    priorityInput.value = 'med';
232	    input.focus();
233	  });
234	
235	  searchInput.addEventListener('input', function () {
236	    search = searchInput.value;
237	    render();
238	  });
239	
240	  filterButtons.forEach(function (b) {
241	    b.addEventListener('click', function () {
242	      filter = b.dataset.filter;
243	      render();
244	    });
245	  });
246	
247	  // Bulk actions change flags or remove items only; they never reorder the array,
248	  // so render() still applies active/completed grouping, priority, and insertion order.
249	  document.querySelector('[data-testid="bulk-mark-all"]').addEventListener('click', function () {
250	    todos.forEach(function (t) { t.completed = true; });
251	    save();
252	    render();
253	  });
254	
255	  document.querySelector('[data-testid="bulk-clear-completed"]').addEventListener('click', function () {
256	    todos = todos.filter(function (t) { return !t.completed; });
257	    save();
258	    render();
259	  });
260	
261	  // Re-render when the local calendar day changes so overdue flags stay current.
262	  setInterval(function () {
263	    if (!editing && localToday(new Date()) !== renderedDay) render();
264	  }, 60000);
265	
266	  render();
267	})();
268	</script>
269	</body>
270	</html>
